//! The paint index: every hobby paint of the miniature-paints tables, with
//! its kind, searchable by name and by colour. Section 2 of
//! `docs/PAINT-RACK.md`.
//!
//! The index is `assets/paints/index.tsv`, generated by
//! `scripts/paint_index.py` and built into the application. It is read
//! once, the first time it is asked for.
//!
//! Colour distance is OKLab's: Euclidean in a space made so that equal
//! steps look equal. CIEDE2000 is the reference and costs several times
//! as much a pair, for differences that do not change which of eleven
//! thousand paints comes first (open question 2 of the design, taken this
//! way and said so there).

use std::sync::OnceLock;

use brokkr_core::paint::layers::Blend;

/// What sort of paint a paint is, which decides how it lays and which
/// blend its layer takes. See section 4 of the design.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Kind {
    #[default]
    Paint,
    Air,
    Metallic,
    Contrast,
    Wash,
    Stain,
    Primer,
    Spray,
    Dry,
    Effect,
    /// A colour reference, Pantone or RAL: not a paint, and only searched
    /// when asked for.
    Reference,
}

impl Kind {
    pub(crate) const ALL: [Kind; 11] = [
        Kind::Paint,
        Kind::Air,
        Kind::Metallic,
        Kind::Contrast,
        Kind::Wash,
        Kind::Stain,
        Kind::Primer,
        Kind::Spray,
        Kind::Dry,
        Kind::Effect,
        Kind::Reference,
    ];

    pub(crate) fn label(self) -> &'static str {
        match self {
            Kind::Paint => "Paint",
            Kind::Air => "Air",
            Kind::Metallic => "Metallic",
            Kind::Contrast => "Contrast",
            Kind::Wash => "Wash",
            Kind::Stain => "Stain",
            Kind::Primer => "Primer",
            Kind::Spray => "Spray",
            Kind::Dry => "Dry",
            Kind::Effect => "Effect",
            Kind::Reference => "Reference",
        }
    }

    /// How it is written in the index and in a rack's file.
    pub(crate) fn code(self) -> &'static str {
        match self {
            Kind::Paint => "paint",
            Kind::Air => "air",
            Kind::Metallic => "metallic",
            Kind::Contrast => "contrast",
            Kind::Wash => "wash",
            Kind::Stain => "stain",
            Kind::Primer => "primer",
            Kind::Spray => "spray",
            Kind::Dry => "dry",
            Kind::Effect => "effect",
            Kind::Reference => "reference",
        }
    }

    pub(crate) fn from_code(code: &str) -> Option<Kind> {
        Kind::ALL.into_iter().find(|kind| kind.code() == code)
    }

    /// The blend a layer of this kind of paint takes: a wash pools, a
    /// stain glazes, a contrast tints by what is under it, and the rest
    /// cover.
    pub(crate) fn blend(self) -> Blend {
        match self {
            Kind::Wash => Blend::Wash,
            Kind::Stain => Blend::Glaze,
            Kind::Contrast => Blend::Contrast,
            _ => Blend::Normal,
        }
    }
}

impl std::fmt::Display for Kind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.label())
    }
}

/// One paint of the index.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct IndexPaint {
    /// As the tables name it, `Citadel_Colour`; see [`IndexPaint::maker`].
    pub brand: &'static str,
    pub line: &'static str,
    pub name: &'static str,
    pub code: &'static str,
    /// sRGB.
    pub rgb: [u8; 3],
    pub kind: Kind,
    /// `a` airbrush, `s` spray, `D` `B` `L` a Foundry triad's dark, base
    /// and light.
    pub flags: &'static str,
}

impl IndexPaint {
    /// The brand as it is shown.
    pub(crate) fn maker(&self) -> String {
        self.brand.replace('_', " ")
    }
}

const TABLE: &str = include_str!("../../../assets/paints/index.tsv");

/// Every paint of the index, read the first time it is asked for.
pub(crate) fn index() -> &'static [IndexPaint] {
    static INDEX: OnceLock<Vec<IndexPaint>> = OnceLock::new();
    INDEX.get_or_init(|| read(TABLE))
}

/// The paints in an index file. A line it cannot read is left out.
fn read(table: &'static str) -> Vec<IndexPaint> {
    table
        .lines()
        .filter_map(|line| {
            let mut fields = line.split('\t');
            let brand = fields.next()?;
            let line_name = fields.next()?;
            let name = fields.next()?;
            let code = fields.next()?;
            let rgb = hex(fields.next()?)?;
            let kind = Kind::from_code(fields.next()?)?;
            let flags = fields.next().unwrap_or("");
            Some(IndexPaint { brand, line: line_name, name, code, rgb, kind, flags })
        })
        .collect()
}

/// Six hex digits as a colour.
pub(crate) fn hex(text: &str) -> Option<[u8; 3]> {
    let text = text.trim().trim_start_matches('#');
    if text.len() != 6 || !text.is_ascii() {
        return None;
    }
    let byte = |at: usize| u8::from_str_radix(&text[at..at + 2], 16).ok();
    Some([byte(0)?, byte(2)?, byte(4)?])
}

/// The brands of the index, as the tables name them, sorted.
pub(crate) fn brands() -> &'static [&'static str] {
    static BRANDS: OnceLock<Vec<&'static str>> = OnceLock::new();
    BRANDS.get_or_init(|| {
        let mut brands: Vec<&'static str> = index().iter().map(|paint| paint.brand).collect();
        brands.sort_unstable();
        brands.dedup();
        brands
    })
}

/// What a search is narrowed to, beside its words.
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub(crate) struct Filter<'a> {
    pub kind: Option<Kind>,
    pub brand: Option<&'a str>,
}

impl Filter<'_> {
    fn admits(&self, paint: &IndexPaint) -> bool {
        // A colour reference only when references are asked for.
        let kind = match self.kind {
            Some(kind) => paint.kind == kind,
            None => paint.kind != Kind::Reference,
        };
        kind && self.brand.is_none_or(|brand| paint.brand == brand)
    }
}

/// The paints whose name, brand, line or code the words of `text` find,
/// best first, at most `limit`. Words in any order; each may be the start
/// of a word, a part of a code, or, from four letters, a word one slip
/// away (a letter wrong, missing, extra or two swapped). With no words,
/// every paint the filter admits, by brand and name.
pub(crate) fn search(text: &str, filter: Filter<'_>, limit: usize) -> Vec<usize> {
    let text = text.trim().to_lowercase();
    let tokens: Vec<&str> = text.split_whitespace().collect();
    let mut found: Vec<(u32, usize)> = Vec::new();
    for (at, paint) in index().iter().enumerate() {
        if !filter.admits(paint) {
            continue;
        }
        if tokens.is_empty() {
            found.push((0, at));
            continue;
        }
        if let Some(score) = score(paint, &text, &tokens) {
            found.push((score, at));
        }
    }
    if tokens.is_empty() {
        // Nothing asked: the index as a shelf is read, by brand and name.
        found.sort_by(|(_, a), (_, b)| {
            let (a, b) = (&index()[*a], &index()[*b]);
            (a.brand, a.name, a.line).cmp(&(b.brand, b.name, b.line))
        });
        return found.into_iter().take(limit).map(|(_, at)| at).collect();
    }
    found.sort_by(|(one, a), (other, b)| {
        let (a, b) = (&index()[*a], &index()[*b]);
        one.cmp(other)
            .then(a.name.len().cmp(&b.name.len()))
            .then_with(|| a.name.cmp(b.name))
            .then_with(|| a.brand.cmp(b.brand))
            .then_with(|| a.line.cmp(b.line))
    });
    found.into_iter().take(limit).map(|(_, at)| at).collect()
}

/// How well `tokens` find `paint`, lower being better, or `None` when one
/// of them does not.
fn score(paint: &IndexPaint, text: &str, tokens: &[&str]) -> Option<u32> {
    let name = paint.name.to_lowercase();
    let code = paint.code.to_lowercase();
    if name == text || (!code.is_empty() && code == text) {
        return Some(0);
    }
    let name_words: Vec<&str> = name.split(|c: char| !c.is_alphanumeric()).collect();
    let rest = format!("{} {}", paint.brand, paint.line).to_lowercase();
    let rest_words: Vec<&str> =
        rest.split(|c: char| !c.is_alphanumeric()).filter(|word| !word.is_empty()).collect();
    let mut score = if name.starts_with(text) { 1 } else { 3 };
    let mut all_in_name = true;
    for token in tokens {
        let prefix = |word: &&str| word.starts_with(token);
        if name_words.iter().any(prefix) {
            continue;
        }
        all_in_name = false;
        if rest_words.iter().any(prefix) || (!code.is_empty() && code.contains(token)) {
            continue;
        }
        // By characters, not bytes: names carry accents.
        let letters = token.chars().count();
        let near = |word: &&str| {
            letters >= 4 && word.chars().count() + 1 >= letters && {
                let cut: String = word.chars().take(letters).collect();
                slips(word, token) <= 1 || slips(&cut, token) <= 1
            }
        };
        if name_words.iter().any(near) || rest_words.iter().any(near) {
            score += 4;
            continue;
        }
        return None;
    }
    if score == 3 && all_in_name {
        score = 2;
    }
    Some(score)
}

/// How many slips apart two words are: a letter wrong, missing or extra,
/// or two next to each other swapped, each one.
fn slips(one: &str, other: &str) -> usize {
    let a: Vec<char> = one.chars().collect();
    let b: Vec<char> = other.chars().collect();
    let mut rows = vec![vec![0usize; b.len() + 1]; a.len() + 1];
    for (i, row) in rows.iter_mut().enumerate() {
        row[0] = i;
    }
    for (j, cell) in rows[0].iter_mut().enumerate() {
        *cell = j;
    }
    for i in 1..=a.len() {
        for j in 1..=b.len() {
            let cost = usize::from(a[i - 1] != b[j - 1]);
            let mut best =
                (rows[i - 1][j] + 1).min(rows[i][j - 1] + 1).min(rows[i - 1][j - 1] + cost);
            if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
                best = best.min(rows[i - 2][j - 2] + 1);
            }
            rows[i][j] = best;
        }
    }
    rows[a.len()][b.len()]
}

/// A colour in OKLab: lightness and two axes of hue.
pub(crate) fn oklab(rgb: [u8; 3]) -> [f32; 3] {
    let linear = |c: u8| {
        let c = f32::from(c) / 255.0;
        if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }
    };
    let [r, g, b] = rgb.map(linear);
    let l = 0.412_221_47 * r + 0.536_332_55 * g + 0.051_445_995 * b;
    let m = 0.211_903_5 * r + 0.680_699_5 * g + 0.107_396_96 * b;
    let s = 0.088_302_46 * r + 0.281_718_85 * g + 0.629_978_7 * b;
    let [l, m, s] = [l.cbrt(), m.cbrt(), s.cbrt()];
    [
        0.210_454_26 * l + 0.793_617_8 * m - 0.004_072_047 * s,
        1.977_998_5 * l - 2.428_592_2 * m + 0.450_593_7 * s,
        0.025_904_037 * l + 0.782_771_77 * m - 0.808_675_77 * s,
    ]
}

/// How far apart two colours look, in OKLab. A hundredth is about as
/// little as an eye tells apart side by side.
pub(crate) fn distance(one: [u8; 3], other: [u8; 3]) -> f32 {
    let (a, b) = (oklab(one), oklab(other));
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

/// The paints the filter admits nearest `rgb`, nearest first, at most
/// `limit`, with how far each is.
pub(crate) fn nearest(rgb: [u8; 3], filter: Filter<'_>, limit: usize) -> Vec<(usize, f32)> {
    let mut found: Vec<(usize, f32)> = index()
        .iter()
        .enumerate()
        .filter(|(_, paint)| filter.admits(paint))
        .map(|(at, paint)| (at, distance(rgb, paint.rgb)))
        .collect();
    found.sort_by(|(a, one), (b, other)| one.total_cmp(other).then(a.cmp(b)));
    found.truncate(limit);
    found
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn named(at: usize) -> String {
        let paint = &index()[at];
        format!("{} {}", paint.brand, paint.name)
    }

    /// Every line of the shipped index reads, and the counts are the ones
    /// the design gives.
    #[test]
    fn the_index_reads_whole() {
        assert_eq!(index().len(), TABLE.lines().count(), "a line of the index did not read");
        let count = |kind| index().iter().filter(|paint| paint.kind == kind).count();
        assert_eq!(count(Kind::Reference), 1534);
        assert!(count(Kind::Wash) > 200 && count(Kind::Contrast) > 250);
        assert_eq!(brands().len(), 34);
    }

    /// The examples the design gives: a word finds a paint by the start
    /// of a word of its name, a code finds its paint, and a slip is
    /// forgiven.
    #[test]
    fn the_designs_examples_find_their_paints() {
        let first = |text: &str| named(search(text, Filter::default(), 1)[0]);
        assert!(first("khorne").contains("Khorne Red"), "{}", first("khorne"));
        assert_eq!(first("70.950"), "Vallejo Black");
        assert!(first("nuln oil").contains("Nuln Oil"));
        assert!(first("khrone red").contains("Khorne Red"), "{}", first("khrone red"));
        assert!(first("red khorne").contains("Khorne Red"));
        assert!(search("qqqqzzzz", Filter::default(), 5).is_empty());
        // References only when asked for.
        let pantone = Filter { kind: Some(Kind::Reference), ..Filter::default() };
        assert!(!search("", pantone, 5).is_empty());
        assert!(
            search("", Filter::default(), usize::MAX)
                .iter()
                .all(|at| index()[*at].kind != Kind::Reference)
        );
        // A kind and a brand narrow.
        let washes = Filter { kind: Some(Kind::Wash), brand: Some("Citadel_Colour") };
        let found = search("", washes, usize::MAX);
        assert!(!found.is_empty());
        assert!(found.iter().all(|at| {
            let paint = &index()[*at];
            paint.kind == Kind::Wash && paint.brand == "Citadel_Colour"
        }));
    }

    #[test]
    fn oklab_has_white_at_one_and_black_at_nought() {
        let white = oklab([255, 255, 255]);
        let black = oklab([0, 0, 0]);
        assert!((white[0] - 1.0).abs() < 1e-3 && white[1].abs() < 1e-3 && white[2].abs() < 1e-3);
        assert!(black.iter().all(|v| v.abs() < 1e-6));
    }

    #[test]
    fn slips_counts_each_kind_of_slip_once() {
        assert_eq!(slips("khorne", "khorne"), 0);
        assert_eq!(slips("khorne", "khrone"), 1, "two letters swapped");
        assert_eq!(slips("khorne", "korne"), 1, "a letter missing");
        assert_eq!(slips("khorne", "khornee"), 1, "a letter extra");
        assert_eq!(slips("khorne", "khorny"), 1, "a letter wrong");
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 64, ..ProptestConfig::default() })]

        /// A search for a paint's exact name finds a paint of that name
        /// first.
        #[test]
        fn a_paints_own_name_finds_it_first(at in 0usize..11_443) {
            let at = at % index().len();
            let paint = &index()[at];
            let filter = Filter { kind: Some(paint.kind), brand: None };
            let found = search(paint.name, filter, 1);
            prop_assert!(!found.is_empty(), "{} found nothing", paint.name);
            prop_assert!(index()[found[0]].name.eq_ignore_ascii_case(paint.name),
                "{} found {} first", paint.name, index()[found[0]].name);
        }

        /// The nearest paint to a paint's own colour is no distance from
        /// it, and every one after is no nearer.
        #[test]
        fn the_nearest_to_a_paints_colour_is_that_colour(at in 0usize..11_443) {
            let at = at % index().len();
            let paint = &index()[at];
            let filter = Filter { kind: Some(paint.kind), brand: None };
            let near = nearest(paint.rgb, filter, 8);
            prop_assert!(near[0].1 < 1e-6, "the nearest is {} away", near[0].1);
            prop_assert!(near.windows(2).all(|pair| pair[0].1 <= pair[1].1));
        }

        /// Distance is a distance: none from itself, the same both ways.
        #[test]
        fn distance_is_symmetric_and_none_from_itself(
            a in any::<[u8; 3]>(),
            b in any::<[u8; 3]>(),
        ) {
            prop_assert!(distance(a, a) < 1e-6);
            prop_assert!((distance(a, b) - distance(b, a)).abs() < 1e-6);
        }
    }
}
